query FrameHistory($id: ID!) {
  frameHistory(frameId: $id) {
    versionId
    validFrom
    validTo
    current
    changeSource
    closedByChangeSource
    importJobId
    attributes {
      status
      statusReason
    }
  }
}
'use client'

import { useQuery } from '@apollo/client/react'
import { useEffect, useRef, type ReactElement } from 'react'
import { FrameHistoryDocument } from '../generated/graphql'
import { dateTime, errorMessage, label } from './inventory-api'
import { StatusChip } from './inventory-list'

export function HistoryDialog({
  frameId,
  onClose,
  onJob,
}: {
  frameId: string
  onClose: () => void
  onJob: (jobId: string) => void
}): ReactElement {
  const dialog = useRef<HTMLDialogElement>(null)
  const { data, loading, error } = useQuery(FrameHistoryDocument, {
    variables: { id: frameId },
    fetchPolicy: 'network-only',
    ssr: false,
  })
  useEffect(() => {
    const modal = dialog.current
    modal?.showModal()
    return () => modal?.close()
  }, [])

  return (
    <dialog
      ref={dialog}
      className="history-dialog"
      aria-labelledby="history-title"
      onCancel={onClose}
    >
