from pathlib import Path
import re
import subprocess
from urllib.parse import unquote, urlsplit

files = [
    'README.md',
    'docs/designs/bulk-csv-inventory-import-design.md',
    'docs/designs/bulk-csv-inventory-import.md',
    'docs/designs/full-snapshot-import-design.md',
    'docs/designs/frame-inventory-schema.md',
    'docs/designs/frame-management-grpc-api.md',
    'src/backend/README.md',
]
count = 0
errors = []
for name in files:
    source = Path(name)
    if name in {'docs/designs/frame-inventory-schema.md', 'docs/designs/frame-management-grpc-api.md'}:
        lines = source.read_text().splitlines()
    else:
        diff = subprocess.check_output(['git', 'diff', '--', name], text=True)
        lines = [line[1:] for line in diff.splitlines() if line.startswith('+') and not line.startswith('+++')]
    for destination in re.findall(r'\\]\\(([^)\\s]+)\\)', '\\n'.join(lines)):
        url = urlsplit(destination)
        if url.scheme or url.netloc:
            continue
        target = source.parent / unquote(url.path) if url.path else source
        if not target.exists():
            errors.append(f'{source}: missing {destination}')
        elif url.fragment and target.suffix == '.md':
            heading_ids = {
                re.sub(r'[^\\w\\- ]', '', heading.lower()).replace(' ', '-')
                for heading in re.findall(r'^#{1,6} (.*)', target.read_text(), re.MULTILINE)
            }
            if re.fullmatch(r'L\\d+(?:-L\\d+)?', url.fragment):
                last_line = int(url.fragment.split('L')[-1])
                if last_line > len(target.read_text().splitlines()):
                    errors.append(f'{source}: missing lines for {destination}')
            elif url.fragment not in heading_ids:
                errors.append(f'{source}: missing anchor in {destination}')
        count += 1
assert not errors, '\\n' + '\\n'.join(errors)
print(f'Validated {count} local Markdown links.')
